import{_ as e,a,o as r,a4 as o}from"./chunks/framework.-FZumj2l.js";const g=JSON.parse('{"title":"REST ↔ GraphQL mapping","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/rest-graphql-mapping/index.md","filePath":"api/rest-graphql-mapping/index.md","lastUpdated":1784902076000}'),d={name:"api/rest-graphql-mapping/index.md"};function s(i,t,n,p,c,h){return r(),a("div",null,t[0]||(t[0]=[o('<h1 id="rest-↔-graphql-mapping" tabindex="-1">REST ↔ GraphQL mapping <a class="header-anchor" href="#rest-↔-graphql-mapping" aria-label="Permalink to &quot;REST ↔ GraphQL mapping&quot;">​</a></h1><p>REST and GraphQL expose the <strong>same</strong> Bagisto data and behaviour with different syntax. This section is the single reference for translating one to the other — most integration friction comes from mixing the two forms (for example sending a <code>?parent_id=</code> shape into the GraphQL <code>categories</code> field, which has no such argument).</p><p>Read it <strong>REST-first</strong>: find the REST endpoint you know, then read across to its GraphQL equivalent.</p><h2 id="the-two-shapes" tabindex="-1">The two shapes <a class="header-anchor" href="#the-two-shapes" aria-label="Permalink to &quot;The two shapes&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>REST</th><th>GraphQL</th></tr></thead><tbody><tr><td>Endpoint</td><td>one URL per operation (<code>GET /api/shop/products</code>)</td><td>one field per operation (<code>products</code>), all on <code>POST /api/graphql</code></td></tr><tr><td>Filters</td><td>query string — <code>?category_id=&amp;price=&amp;new=1</code></td><td>a JSON <strong>string</strong> in <code>filter:</code> — <code>filter: &quot;{\\&quot;category_id\\&quot;:\\&quot;22\\&quot;}&quot;</code></td></tr><tr><td>Sort</td><td><code>?sort=price-asc</code></td><td><code>sortKey: &quot;PRICE&quot;, reverse: false</code></td></tr><tr><td>Pagination</td><td><code>?page=2&amp;per_page=30</code> + <code>X-Total-Count</code> headers</td><td><code>first</code>/<code>after</code> cursor + <code>pageInfo</code> (Relay connection)</td></tr><tr><td>Record id</td><td>numeric <code>id</code></td><td><code>id</code> is an <strong>IRI</strong> string; <code>_id</code> is the numeric id — see <a href="/api/graphql-api/identifiers.html">Identifiers</a></td></tr><tr><td>Auth</td><td><code>X-STOREFRONT-KEY</code> + <code>Authorization: Bearer</code></td><td>same headers</td></tr></tbody></table><p>Any key outside the reserved set is treated as a filterable attribute on <strong>both</strong> transports — REST reserves <code>query, sort, order, page, per_page, locale, channel, filter</code>; GraphQL reserves <code>query, sortKey, reverse, first, after, filter</code>.</p><h2 id="shop-mapping-by-area" tabindex="-1">Shop mapping by area <a class="header-anchor" href="#shop-mapping-by-area" aria-label="Permalink to &quot;Shop mapping by area&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>What it covers</th></tr></thead><tbody><tr><td><a href="/api/rest-graphql-mapping/shop/catalog.html">Catalog</a></td><td>Products, categories, attributes — filters, sort, pagination (the biggest source of REST↔GraphQL confusion)</td></tr><tr><td><a href="/api/rest-graphql-mapping/shop/cart-checkout.html">Cart &amp; Checkout</a></td><td>Cart tokens, cart items, coupons, addresses, shipping/payment methods, place order</td></tr><tr><td><a href="/api/rest-graphql-mapping/shop/customer-account.html">Customer Account</a></td><td>Profile, addresses, orders, wishlist, compare, downloadable, reviews, returns (RMA), EU withdrawal, GDPR</td></tr><tr><td><a href="/api/rest-graphql-mapping/shop/auth-context.html">Auth &amp; Context</a></td><td>Storefront key, customer/guest Bearer, <code>token</code> vs <code>apiToken</code>, locale/currency/channel headers</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Admin mapping</p><p>This section currently covers the <strong>Shop</strong> surface. Admin REST ↔ GraphQL mapping is tracked separately.</p></div>',9)]))}const m=e(d,[["render",s]]);export{g as __pageData,m as default};
